1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file guards the plan reader against a silent name substitution.
4	// encoding/json decodes every JSON string by replacing each invalid UTF-8
5	// byte — and each \u escape that is an unpaired surrogate — with U+FFFD, so
6	// the decoded plan no longer contains the names the user actually wrote. A
7	// corrupted name can then collide with a real dataset: a removals entry
8	// written as "源" plus one broken byte decodes to "源�" and would delete the
9	// dataset genuinely named "源�". The reader must not guess which dataset the
10	// user meant, so any name that takes part in the lineage adjustment — the
11	// name of each change record, every upstreams entry, and every removals
12	// entry — is checked against its RAW string literal before the plan is
13	// accepted: a literal carrying bytes that are not valid UTF-8, or a \u
14	// escape forming an unpaired surrogate (a lone high or low surrogate, or a
15	// low surrogate written before its high surrogate), rejects the whole plan,
16	// even when the name would only have matched a dataset that does not exist.
17	//
18	// Only the raw literal can tell corruption apart from a genuine name: the
19	// replacement character itself ("�", or the equivalent JSON escape) is legal and
20	// stays accepted, as is every correctly paired surrogate escape. Names that
21	// merely LOOK like escapes (a backslash followed by an ordinary letter) are
22	// plain text to JSON and are never rejected for that reason.
23	//
24	// The scan walks the document with the same field recognition the plan
25	// reader and the duplicate-field scan use — known fields matched after JSON
26	// unescaping with Unicode case folding — so a name spelled "Name" or
27	// "name" is checked exactly like "name". Unknown fields and everything
28	// nested inside them are skipped; their strings never took part in the
29	// adjustment and are not checked. A document too malformed to walk is left
30	// to the regular parse, exactly as in duplicate_fields.go.
31	package chainledger
32	
33	import (
34		"encoding/json"
35		"fmt"
36		"strings"
37		"unicode/utf8"
38	)
39	
40	// checkPlanNameEncoding scans the raw plan JSON and rejects the whole plan
41	// when any name that participates in the adjustment — changes[i].name, any
42	// changes[i].upstreams[j], or any removals[i] — is written with a string
43	// literal the decoder cannot read faithfully (invalid UTF-8 bytes or an
44	// unpaired surrogate escape). The error names the field and the zero-based
45	// record or array position, and says which of the two corruptions occurred.
46	func checkPlanNameEncoding(data []byte) error {
47		return runFieldScan(data, func(dec *json.Decoder) error {
48			tok, err := scanToken(dec)
49			if err != nil {
50				return err
51			}
52			if delim, ok := tok.(json.Delim); !ok || delim != '{' {
53				return skipRest(dec, tok) // not an object: the regular parse reports it
54			}
55			for dec.More() {
56				key, err := scanKey(dec)
57				if err != nil {
58					return err
59				}
60				switch {
61				case strings.EqualFold(key, "changes"):
62					err := checkArrayElements(dec, func(dec *json.Decoder, index int) error {
63						return checkNameUpstreamsRecordEncoding(dec, index, "changes", "change record")
64					})
65					if err != nil {
66						return err
67					}
68				case strings.EqualFold(key, "removals"):
69					err := checkArrayElements(dec, func(dec *json.Decoder, index int) error {
70						location := fmt.Sprintf("field %q at index %d", "removals", index)
71						return checkNameStringEncoding(dec, location)
72					})
73					if err != nil {
74						return err
75					}
76				default:
77					// Unknown field: ignored with everything nested inside it.
78					if err := skipValue(dec); err != nil {
79						return err
80					}
81				}
82			}
83			_, err = scanToken(dec) // closing '}'
84			return err
85		})
86	}
87	
88	// checkNameUpstreamsRecordEncoding scans one record that carries a checked
89	// "name" string and a checked "upstreams" string array — a change record in a
90	// plan (arrayField "changes", recordKind "change record") or a dataset record
91	// in a graph (arrayField "datasets", recordKind "dataset record"). The raw
92	// literals of the name and of every upstream element are validated; every
93	// other field is skipped. index is the record's zero-based position in its
94	// array, used together with the array field and record kind in error
95	// locations, so the plan and graph readers can never judge one record shape
96	// differently.
97	func checkNameUpstreamsRecordEncoding(dec *json.Decoder, index int, arrayField, recordKind string) error {
98		tok, err := scanToken(dec)
99		if err != nil {
100			return err
101		}
102		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
103			return skipRest(dec, tok) // not an object: the regular parse reports it
104		}
105		for dec.More() {
106			key, err := scanKey(dec)
107			if err != nil {
108				return err
109			}
110			switch {
111			case strings.EqualFold(key, "name"):
112				location := fmt.Sprintf("field %q in the %s at index %d of %q", "name", recordKind, index, arrayField)
113				if err := checkNameStringEncoding(dec, location); err != nil {
114					return err
115				}
116			case strings.EqualFold(key, "upstreams"):
117				err := checkArrayElements(dec, func(dec *json.Decoder, item int) error {
118					location := fmt.Sprintf("field %q at index %d in the %s at index %d of %q", "upstreams", item, recordKind, index, arrayField)
119					return checkNameStringEncoding(dec, location)
120				})
121				if err != nil {
122					return err
123				}
124			default:
125				if err := skipValue(dec); err != nil {
126					return err
127				}
128			}
129		}
130		_, err = scanToken(dec) // closing '}'
131		return err
132	}
133	
134	// checkNameStringEncoding consumes one value and, when it is a string
135	// literal, validates its raw bytes with validateNameStringLiteral. A
136	// non-string value is skipped: the regular parse reports the type error.
137	func checkNameStringEncoding(dec *json.Decoder, location string) error {
138		var raw json.RawMessage
139		if err := dec.Decode(&raw); err != nil {
140			return errAbortScan
141		}
142		if len(raw) < 2 || raw[0] != '"' {
143			return nil
144		}
145		return validateNameStringLiteral(raw, location)
146	}
147	
148	// validateNameStringLiteral checks one raw JSON string literal (surrounding
149	// quotes included) for the two corruptions the decoder would silently
150	// rewrite to U+FFFD: bytes that are not valid UTF-8, and \u escapes forming
151	// an unpaired surrogate. The literal is known to be syntactically valid
152	// JSON (the regular parse already accepted the document), so escapes are
153	// well-formed; anything else unexpected aborts the scan and is left to that
154	// parse. location identifies the field and position in the error.
155	func validateNameStringLiteral(raw []byte, location string) error {
156		end := len(raw) - 1 // index of the closing quote
157		for i := 1; i < end; {
158			c := raw[i]
159			switch {
160			case c == '\\':
161				if i+1 >= end {
162					return errAbortScan
163				}
164				if raw[i+1] != 'u' {
165					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
166					continue
167				}
168				if i+6 > end {
169					return errAbortScan
170				}
171				cp, ok := hex4(raw[i+2 : i+6])
172				if !ok {
173					return errAbortScan
174				}
175				i += 6
176				switch {
177				case isHighSurrogate(cp):
178					// A high surrogate is legal only as the first half of a
179					// pair: the very next escape must be its low surrogate.
180					if i+6 <= end && raw[i] == '\\' && raw[i+1] == 'u' {
181						if low, ok := hex4(raw[i+2 : i+6]); ok && isLowSurrogate(low) {
182							i += 6
183							continue
184						}
185					}
186					return unpairedSurrogateError(location)
187				case isLowSurrogate(cp):
188					// A lone low surrogate — including one written before its
189					// high surrogate — never forms a pair.
190					return unpairedSurrogateError(location)
191				}
192			case c < utf8.RuneSelf:
193				i++
194			default:
195				// A genuine U+FFFD decodes with size 3 and is accepted; only a
196				// byte the decoder cannot map (size 1) is corruption.
197				r, size := utf8.DecodeRune(raw[i:end])
198				if r == utf8.RuneError && size == 1 {
199					return invalidUTF8BytesError(location)
200				}
201				i += size
202			}
203		}
204		return nil
205	}
206	
207	// hex4 parses exactly four hexadecimal digits (one \u escape unit).
208	func hex4(b []byte) (rune, bool) {
209		var v rune
210		for _, c := range b {
211			v <<= 4
212			switch {
213			case c >= '0' && c <= '9':
214				v |= rune(c - '0')
215			case c >= 'a' && c <= 'f':
216				v |= rune(c-'a') + 10
217			case c >= 'A' && c <= 'F':
218				v |= rune(c-'A') + 10
219			default:
220				return 0, false
221			}
222		}
223		return v, true
224	}
225	
226	func isHighSurrogate(cp rune) bool { return cp >= 0xD800 && cp <= 0xDBFF }
227	func isLowSurrogate(cp rune) bool  { return cp >= 0xDC00 && cp <= 0xDFFF }
228	
229	// invalidUTF8BytesError reports a name whose raw string literal carries
230	// bytes that are not valid UTF-8.
231	func invalidUTF8BytesError(location string) error {
232		return fmt.Errorf("%w: %s contains invalid UTF-8 bytes", ErrInvalidArgument, location)
233	}
234	
235	// unpairedSurrogateError reports a name whose \u escapes form an unpaired
236	// surrogate (a lone high or low surrogate, or a low surrogate before its
237	// high surrogate).
238	func unpairedSurrogateError(location string) error {
239		return fmt.Errorf("%w: %s contains an unpaired surrogate escape", ErrInvalidArgument, location)
240	}
241

