234					"😀x🌐",
235				},
236				"cjk combining marks casing and spaces": {
237					`{"datasets":[{"name":" 数据 Éé ","upstreams":[]}]}`,
238					" 数据 Éé ",
239				},
240				"backslash before ordinary letter": {
241					`{"datasets":[{"name":"a\\nb","upstreams":[]}]}`,
242					`a\nb`,
243				},
244				"backslash before what looks like a surrogate escape": {
245					// The name really contains backslash, 'u', 'd', '8', '0', '0'.
246					`{"datasets":[{"name":"x\\ud800","upstreams":[]}]}`,
247					`x\ud800`,
248				},
249			}
