255					}
256					entry, ok := graph[tc.want]
257					if !ok {
258						t.Fatalf("graph has no dataset %q; datasets %v", tc.want, graph)
259					}
260					if entry.Dataset != tc.want {
261						t.Errorf("dataset = %q, want %q kept verbatim", entry.Dataset, tc.want)
262					}
263				})
264			}
265		})
