90	// TestUnmarshalPlanRejectsUnpairedSurrogates: a \u escape forming an
91	// unpaired surrogate — a lone high or low surrogate, a low surrogate before
92	// its high surrogate, or a high surrogate not immediately followed by its
93	// low surrogate — rejects the whole plan, in every name position. The error
94	// says the surrogate escape is unpaired and locates the field.
95	func TestUnmarshalPlanRejectsUnpairedSurrogates(t *testing.T) {
96		cases := map[string]struct {
97			data     string
98			field    string
99			location string
100		}{
101			"lone high surrogate in name": {
102				`{"changes":[{"name":"a\ud800x","upstreams":[]}]}`,
103				`"name"`, `index 0 of "changes"`,
104			},
105			"high surrogate at end of name": {
106				`{"changes":[{"name":"a\ud800","upstreams":[]}]}`,
107				`"name"`, `index 0 of "changes"`,
108			},
109			"lone low surrogate in name": {
110				`{"changes":[{"name":"a\udc00","upstreams":[]}]}`,
111				`"name"`, `index 0 of "changes"`,
112			},
113			"low surrogate before high surrogate": {
114				`{"changes":[{"name":"a\udc00\ud800","upstreams":[]}]}`,
115				`"name"`, `index 0 of "changes"`,
116			},
117			"high surrogate then non-surrogate escape": {
118				`{"changes":[{"name":"a\ud800\u0041","upstreams":[]}]}`,
119				`"name"`, `index 0 of "changes"`,
120			},
121			"high surrogate then another high surrogate": {
122				`{"changes":[{"name":"a\ud800\ud801","upstreams":[]}]}`,
123				`"name"`, `index 0 of "changes"`,
124			},
125			"surrogate in second change record": {
126				`{"changes":[{"name":"A","upstreams":[]},{"name":"\ud800","upstreams":[]}]}`,
127				`"name"`, `index 1 of "changes"`,
128			},
129			"surrogate in upstream entry": {
130				`{"changes":[{"name":"A","upstreams":["ok","\udfff"]}]}`,
131				`"upstreams"`, `index 1`,
132			},
133			"surrogate in removals entry": {
134				`{"removals":["ok","\ud800"]}`,
135				`"removals"`, `index 1`,
136			},
137			"surrogate naming a dataset that does not exist": {
138				`{"removals":["ghost\ud800"]}`,
139				`"removals"`, `index 0`,
140			},
141		}
142		for name, tc := range cases {
143			t.Run(name, func(t *testing.T) {
144				// Premise: the decoder really would silently rewrite these to
145				// U+FFFD instead of failing, which is why the raw check exists.
146				var decoded struct {
147					Changes []struct {
148						Name string `json:"name"`
149					} `json:"changes"`
150				}
151				_ = json.Unmarshal([]byte(tc.data), &decoded)
152	
153				_, err := UnmarshalPlan([]byte(tc.data))
154				if !errors.Is(err, ErrInvalidArgument) {
155					t.Fatalf("err = %v, want ErrInvalidArgument", err)
156				}
157				msg := err.Error()
158				if !strings.Contains(msg, "unpaired surrogate") {
159					t.Errorf("err = %q, want it to say the surrogate escape is unpaired", msg)
160				}
161				if strings.Contains(msg, "invalid UTF-8 bytes") {
162					t.Errorf("err = %q, a surrogate problem must not be reported as invalid bytes", msg)
163				}
164				if !strings.Contains(msg, tc.field) {
165					t.Errorf("err = %q, want it to name field %s", msg, tc.field)
166				}
167				if !strings.Contains(msg, tc.location) {
168					t.Errorf("err = %q, want it to locate %s", msg, tc.location)
169				}
170			})
171		}
