173	
174	// TestUnmarshalPlanCorruptNameRejectsWholePlan: one corrupt name refuses
175	// the entire plan — the other, perfectly legal adjustments in the same
176	// batch must not take effect either.
177	func TestUnmarshalPlanCorruptNameRejectsWholePlan(t *testing.T) {
178		data := `{"changes":[{"name":"A","upstreams":[]},{"name":"b` + "\xff" + `","upstreams":[]}],"removals":["C"]}`
