242	// TestUnmarshalPlanIgnoresCorruptStringsInUnknownFields: unknown fields and
243	// everything nested inside them keep their ignore-everything behavior —
244	// their strings never take part in the adjustment and are not checked, even
245	// when they spell a known field name one level down.
246	func TestUnmarshalPlanIgnoresCorruptStringsInUnknownFields(t *testing.T) {
247		cases := map[string]string{
248			"corrupt string in unknown top-level field": `{"meta":"a\ud800","changes":[{"name":"A","upstreams":[]}]}`,
249			"corrupt bytes in unknown record field":     `{"changes":[{"name":"A","note":"x` + "\xff" + `","upstreams":[]}]}`,
250			"known field names nested inside unknown field": `{"also":{"changes":[{"name":"\ud800"}],"removals":["g` + "\xff" + `"]},` +
251				`"changes":[{"name":"A","upstreams":[]}]}`,
252			"deeply nested corrupt strings in unknown field": `{"changes":[{"name":"A","upstreams":[],"extra":{"deep":["\udc00",{"k":"v` + "\xfe" + `"}]}}]}`,
253			"unknown field that merely prefixes a known one": `{"changesX":[{"name":"\ud800"}],"removals2":["a` + "\xff" + `"],"changes":[]}`,
254		}
