259				}
260			})
261		}
262	}
263	
264	// TestUnmarshalPlanEquivalentEscapesSameDataset: legal text written
265	// directly and the same text written with equivalent JSON escapes name the
266	// same dataset and produce the same report.
267	func TestUnmarshalPlanEquivalentEscapesSameDataset(t *testing.T) {
268		graphData := `{"datasets":[{"name":"数据集","upstreams":[]},{"name":"源�","upstreams":[]}]}`
269		graph, err := UnmarshalGraphFile([]byte(graphData))
270		if err != nil {
