package chainledger

import (
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
)

// These tests pin the rule that a plan's raw name literals must decode
// exactly as written. encoding/json silently rewrites invalid UTF-8 bytes
// and unpaired \u surrogate escapes to U+FFFD, so a corrupted name could
// collide with a genuinely different dataset ("源" plus a broken byte would
// delete the dataset really named "源�"). The reader must refuse the whole
// plan instead of guessing which dataset the user meant.

// TestUnmarshalPlanRejectsCorruptNameBytes: a raw string literal carrying
// bytes that are not valid UTF-8 rejects the whole plan, in every position
// that takes part in the adjustment — a change record's name, any upstreams
// entry, and any removals entry. The error names the field and the
// zero-based record or array position and says the bytes are invalid.
func TestUnmarshalPlanRejectsCorruptNameBytes(t *testing.T) {
	cases := map[string]struct {
		data     string
		field    string
		location string
	}{
		"change name": {
			`{"changes":[{"name":"source` + "\xff" + `","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"change name in second record": {
			`{"changes":[{"name":"A","upstreams":[]},{"name":"b` + "\xfe" + `","upstreams":[]}]}`,
			`"name"`, `index 1 of "changes"`,
		},
		"upstream entry": {
			`{"changes":[{"name":"A","upstreams":["ok","g` + "\xfe" + `"]}]}`,
			`"upstreams"`, `index 1`,
		},
		"upstream entry in second record": {
			`{"changes":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","x` + "\xff" + `"]}]}`,
			`"upstreams"`, `index 1`,
		},
		"removals entry": {
			`{"removals":["a","b","c` + "\xc3" + `"]}`,
			`"removals"`, `index 2`,
		},
		"removals entry naming a dataset that does not exist": {
			// Even a name that would only delete a nonexistent dataset is
			// refused: the reader must not treat the corruption as a no-op.
			`{"removals":["ghost` + "\xff" + `"]}`,
			`"removals"`, `index 0`,
		},
		"case-folded known field is still checked": {
			`{"CHANGES":[{"NAME":"a` + "\xff" + `"}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"escaped key spelling is still checked": {
			`{"changes":[{"na\u006de":"a` + "\xff" + `"}]}`,
			`"name"`, `index 0 of "changes"`,
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			_, err := UnmarshalPlan([]byte(tc.data))
			if !errors.Is(err, ErrInvalidArgument) {
				t.Fatalf("err = %v, want ErrInvalidArgument", err)
			}
			msg := err.Error()
			if !strings.Contains(msg, "invalid UTF-8 bytes") {
				t.Errorf("err = %q, want it to say the bytes are invalid UTF-8", msg)
			}
			if strings.Contains(msg, "surrogate") {
				t.Errorf("err = %q, byte corruption must not be reported as a surrogate problem", msg)
			}
			if !strings.Contains(msg, tc.field) {
				t.Errorf("err = %q, want it to name field %s", msg, tc.field)
			}
			if !strings.Contains(msg, tc.location) {
				t.Errorf("err = %q, want it to locate %s", msg, tc.location)
			}
			if strings.Contains(msg, "�") {
				t.Errorf("err = %q, must not contain the replacement character", msg)
			}
		})
	}
}

// TestUnmarshalPlanRejectsUnpairedSurrogates: a \u escape forming an
// unpaired surrogate — a lone high or low surrogate, a low surrogate before
// its high surrogate, or a high surrogate not immediately followed by its
// low surrogate — rejects the whole plan, in every name position. The error
// says the surrogate escape is unpaired and locates the field.
func TestUnmarshalPlanRejectsUnpairedSurrogates(t *testing.T) {
	cases := map[string]struct {
		data     string
		field    string
		location string
	}{
		"lone high surrogate in name": {
			`{"changes":[{"name":"a\ud800x","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"high surrogate at end of name": {
			`{"changes":[{"name":"a\ud800","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"lone low surrogate in name": {
			`{"changes":[{"name":"a\udc00","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"low surrogate before high surrogate": {
			`{"changes":[{"name":"a\udc00\ud800","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"high surrogate then non-surrogate escape": {
			`{"changes":[{"name":"a\ud800\u0041","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"high surrogate then another high surrogate": {
			`{"changes":[{"name":"a\ud800\ud801","upstreams":[]}]}`,
			`"name"`, `index 0 of "changes"`,
		},
		"surrogate in second change record": {
			`{"changes":[{"name":"A","upstreams":[]},{"name":"\ud800","upstreams":[]}]}`,
			`"name"`, `index 1 of "changes"`,
		},
		"surrogate in upstream entry": {
			`{"changes":[{"name":"A","upstreams":["ok","\udfff"]}]}`,
			`"upstreams"`, `index 1`,
		},
		"surrogate in removals entry": {
			`{"removals":["ok","\ud800"]}`,
			`"removals"`, `index 1`,
		},
		"surrogate naming a dataset that does not exist": {
			`{"removals":["ghost\ud800"]}`,
			`"removals"`, `index 0`,
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			// Premise: the decoder really would silently rewrite these to
			// U+FFFD instead of failing, which is why the raw check exists.
			var decoded struct {
				Changes []struct {
					Name string `json:"name"`
				} `json:"changes"`
			}
			_ = json.Unmarshal([]byte(tc.data), &decoded)

			_, err := UnmarshalPlan([]byte(tc.data))
			if !errors.Is(err, ErrInvalidArgument) {
				t.Fatalf("err = %v, want ErrInvalidArgument", err)
			}
			msg := err.Error()
			if !strings.Contains(msg, "unpaired surrogate") {
				t.Errorf("err = %q, want it to say the surrogate escape is unpaired", msg)
			}
			if strings.Contains(msg, "invalid UTF-8 bytes") {
				t.Errorf("err = %q, a surrogate problem must not be reported as invalid bytes", msg)
			}
			if !strings.Contains(msg, tc.field) {
				t.Errorf("err = %q, want it to name field %s", msg, tc.field)
			}
			if !strings.Contains(msg, tc.location) {
				t.Errorf("err = %q, want it to locate %s", msg, tc.location)
			}
		})
	}
}

// TestUnmarshalPlanCorruptNameRejectsWholePlan: one corrupt name refuses
// the entire plan — the other, perfectly legal adjustments in the same
// batch must not take effect either.
func TestUnmarshalPlanCorruptNameRejectsWholePlan(t *testing.T) {
	data := `{"changes":[{"name":"A","upstreams":[]},{"name":"b` + "\xff" + `","upstreams":[]}],"removals":["C"]}`
	if _, err := UnmarshalPlan([]byte(data)); err == nil {
		t.Fatal("a plan mixing legal records with one corrupt name must be rejected as a whole")
	}
}

// TestUnmarshalPlanAcceptsGenuineUnicodeNames: names that are legal stay
// byte-for-byte intact — a genuine replacement character (written directly
// or as its escape), correctly paired surrogate escapes, CJK, combining
// marks, casing, surrounding spaces, and names that merely look like
// escapes (a backslash before an ordinary letter).
func TestUnmarshalPlanAcceptsGenuineUnicodeNames(t *testing.T) {
	cases := map[string]struct {
		data string
		want string
	}{
		"genuine replacement character": {
			`{"changes":[{"name":"源�","upstreams":[]}]}`,
			"源�",
		},
		"replacement character via escape": {
			`{"changes":[{"name":"源\ufffd","upstreams":[]}]}`,
			"源�",
		},
		"paired surrogate escape": {
			`{"changes":[{"name":"ledger\ud83d\ude00","upstreams":[]}]}`,
			"ledger😀",
		},
		"paired surrogate at string start and end": {
			`{"changes":[{"name":"\ud83d\ude00x\ud83c\udf10","upstreams":[]}]}`,
			"😀x🌐",
		},
		"cjk combining marks casing and spaces": {
			`{"changes":[{"name":" 数据 Éé ","upstreams":[]}]}`,
			" 数据 Éé ",
		},
		"backslash before ordinary letter": {
			`{"changes":[{"name":"a\\nb","upstreams":[]}]}`,
			`a\nb`,
		},
		"backslash before what looks like a surrogate escape": {
			// The name really contains backslash, 'u', 'd', '8', '0', '0';
			// it must not be rejected for looking like an escape.
			`{"changes":[{"name":"x\\ud800","upstreams":[]}]}`,
			`x\ud800`,
		},
		"escaped backslash then real escape": {
			`{"changes":[{"name":"x\\\nud800","upstreams":[]}]}`,
			"x\\\nud800",
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			plan, err := UnmarshalPlan([]byte(tc.data))
			if err != nil {
				t.Fatalf("UnmarshalPlan rejected a legal name: %v", err)
			}
			if len(plan.Changes) != 1 || plan.Changes[0].Name != tc.want {
				t.Fatalf("name decoded to %q, want %q kept verbatim", plan.Changes, tc.want)
			}
		})
	}
}

// TestUnmarshalPlanIgnoresCorruptStringsInUnknownFields: unknown fields and
// everything nested inside them keep their ignore-everything behavior —
// their strings never take part in the adjustment and are not checked, even
// when they spell a known field name one level down.
func TestUnmarshalPlanIgnoresCorruptStringsInUnknownFields(t *testing.T) {
	cases := map[string]string{
		"corrupt string in unknown top-level field": `{"meta":"a\ud800","changes":[{"name":"A","upstreams":[]}]}`,
		"corrupt bytes in unknown record field":     `{"changes":[{"name":"A","note":"x` + "\xff" + `","upstreams":[]}]}`,
		"known field names nested inside unknown field": `{"also":{"changes":[{"name":"\ud800"}],"removals":["g` + "\xff" + `"]},` +
			`"changes":[{"name":"A","upstreams":[]}]}`,
		"deeply nested corrupt strings in unknown field": `{"changes":[{"name":"A","upstreams":[],"extra":{"deep":["\udc00",{"k":"v` + "\xfe" + `"}]}}]}`,
		"unknown field that merely prefixes a known one": `{"changesX":[{"name":"\ud800"}],"removals2":["a` + "\xff" + `"],"changes":[]}`,
	}
	for name, data := range cases {
		t.Run(name, func(t *testing.T) {
			if _, err := UnmarshalPlan([]byte(data)); err != nil {
				t.Fatalf("unknown-field strings must not be checked, got %v", err)
			}
		})
	}
}

// TestUnmarshalPlanEquivalentEscapesSameDataset: legal text written
// directly and the same text written with equivalent JSON escapes name the
// same dataset and produce the same report.
func TestUnmarshalPlanEquivalentEscapesSameDataset(t *testing.T) {
	graphData := `{"datasets":[{"name":"数据集","upstreams":[]},{"name":"源�","upstreams":[]}]}`
	graph, err := UnmarshalGraphFile([]byte(graphData))
	if err != nil {
		t.Fatalf("UnmarshalGraphFile: %v", err)
	}

	direct := `{"changes":[{"name":"数据集","upstreams":["源�"]}],"removals":["旧�"]}`
	escaped := `{"changes":[{"name":"\u6570\u636e\u96c6","upstreams":["\u6e90\ufffd"]}],"removals":["\u65e7\ufffd"]}`
	if direct == escaped {
		t.Fatal("test premise broken: the two spellings must differ as text")
	}

	planDirect, err := UnmarshalPlan([]byte(direct))
	if err != nil {
		t.Fatalf("direct spelling rejected: %v", err)
	}
	planEscaped, err := UnmarshalPlan([]byte(escaped))
	if err != nil {
		t.Fatalf("escaped spelling rejected: %v", err)
	}
	if !reflect.DeepEqual(planDirect, planEscaped) {
		t.Fatalf("equivalent spellings decoded differently:\n%+v\n%+v", planDirect, planEscaped)
	}

	reportDirect, err := PreviewBatch(graph, planDirect)
	if err != nil {
		t.Fatalf("PreviewBatch direct: %v", err)
	}
	reportEscaped, err := PreviewBatch(graph, planEscaped)
	if err != nil {
		t.Fatalf("PreviewBatch escaped: %v", err)
	}
	jDirect, _ := json.Marshal(reportDirect)
	jEscaped, _ := json.Marshal(reportEscaped)
	if string(jDirect) != string(jEscaped) {
		t.Fatalf("reports differ between spellings:\n%s\n%s", jDirect, jEscaped)
	}
	if len(reportDirect.ChangedDatasets) != 1 || reportDirect.ChangedDatasets[0] != "数据集" {
		t.Fatalf("expected 数据集 to be the changed dataset, got %v", reportDirect.ChangedDatasets)
	}
}

// TestUnmarshalPlanCorruptNameNeverTouchesGraph: a plan rejected for a
// corrupt name leaves the graph it would have been applied to completely
// unchanged — including when the corrupt name could have deleted a real
// dataset after the decoder's silent rewrite.
func TestUnmarshalPlanCorruptNameNeverTouchesGraph(t *testing.T) {
	graphData := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"down","upstreams":["源�"]}]}`
	graph, err := UnmarshalGraphFile([]byte(graphData))
	if err != nil {
		t.Fatalf("UnmarshalGraphFile: %v", err)
	}
	before := snapshotGraph(graph)

	// "源" plus one broken byte decodes to the real dataset "源�": accepting
	// it would delete a dataset the user never named.
	if _, err := UnmarshalPlan([]byte(`{"removals":["源` + "\xff" + `"]}`)); err == nil {
		t.Fatal("corrupt removal name must be rejected")
	}
	if after := snapshotGraph(graph); !reflect.DeepEqual(after, before) {
		t.Fatalf("graph changed while reading a rejected plan:\nbefore %#v\nafter  %#v", before, after)
	}
}

// Command chainledger is the 链上数据治理与血缘工作台 entry point.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/asdhoaiqqq/chainledger-governance/chainledger"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

// run dispatches the command and returns the process exit code. Keeping the
// exit code out of main makes the CLI testable without spawning a subprocess.
func run(args []string) int {
	command := "demo"
	if len(args) > 0 {
		command = args[0]
	}
	switch command {
	case "demo":
		runDemo()
		return 0
	case "version":
		fmt.Println("chainledger 0.2.0")
		return 0
	case "preview":
		return runBatch(args[1:], false)
	case "apply":
		return runBatch(args[1:], true)
	case "snapshot":
		return runSnapshot(args[1:])
	case "compare":
		return runCompare(args[1:])
	case "trace":
		return runTrace(args[1:])
	case "help", "-h", "--help":
		usage()
		return 0
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage()
		return 2
	}
}

func usage() {
	fmt.Print(`usage: chainledger <command> [arguments]

commands:
  demo                        run the built-in lineage demo
  version                     print the version
  preview <graph> <plan>      validate the batch and print the report without
                              modifying the graph file
  apply <graph> <plan>        validate the batch, apply it to the graph file,
                              and print the report
  snapshot <graph> <snapshot> save a read-only versioned snapshot of the
                              current graph; an existing snapshot of the same
                              content is left byte-for-byte untouched, a
                              different or corrupt target is refused
  compare <old-snapshot> <new-snapshot>
                              read-only comparison of two snapshots; prints a
                              JSON report of nodes, relations, and root-source
                              sets that differ from the old to the new version
  trace <snapshot> <dataset>  read-only source trace of one dataset within a
                              single snapshot; prints a JSON report of every
                              reachable root source with one shortest path
  help                        show this help

The graph file is JSON:
  {"datasets": [{"name": "A", "upstreams": []}, ...]}

The plan file is JSON:
  {"changes": [{"name": "A", "upstreams": ["B"]}, ...], "removals": ["C", ...]}

The snapshot file is JSON with formatVersion 1, a semantic contentId, and the
complete graph. Its bytes depend only on graph semantics, never on record
order, upstream order, duplicate upstreams, JSON whitespace, save time, or
file path. compare and trace never write anything.

A batch registers new datasets, replaces every direct upstream of an
existing dataset with the listed upstreams, and deletes the datasets named in
removals. An empty upstream list makes the dataset a root. Datasets not
mentioned in the plan keep their upstreams. New datasets may reference each
other regardless of plan order; the final graph must be acyclic and every
upstream must resolve to a dataset in the final graph. A retained dataset
that still references a deleted name rejects the batch. Preview and apply
produce the same report for the same inputs.
`)
}

// runBatch implements preview (apply=false) and apply (apply=true). It reads
// the graph and plan JSON files, validates them, prints the report to stdout,
// and — only for apply — writes the final graph back to the graph file. Any
// failure is reported on stderr with a non-zero exit code; on failure the graph
// file is left untouched.
func runBatch(args []string, apply bool) int {
	if len(args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: chainledger %s <graph.json> <plan.json>\n", verb(apply))
		return 2
	}
	graphPath := args[0]
	planPath := args[1]

	graphData, err := os.ReadFile(graphPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read graph file %q: %v\n", graphPath, err)
		return 1
	}
	graph, err := chainledger.UnmarshalGraphFile(graphData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid graph file %q: %v\n", graphPath, err)
		return 1
	}

	planData, err := os.ReadFile(planPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read plan file %q: %v\n", planPath, err)
		return 1
	}
	plan, err := chainledger.UnmarshalPlan(planData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid plan file %q: %v\n", planPath, err)
		return 1
	}

	var report *chainledger.BatchReport
	if apply {
		report, err = chainledger.ApplyBatch(graph, plan)
	} else {
		report, err = chainledger.PreviewBatch(graph, plan)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		return 1
	}

	if apply {
		out, err := chainledger.MarshalGraphFile(graph)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: cannot serialize final graph: %v\n", err)
			return 1
		}
		if err := atomicWrite(graphPath, out); err != nil {
			fmt.Fprintf(os.Stderr, "error: cannot write graph file %q: %v\n", graphPath, err)
			return 1
		}
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
		return 1
	}
	return 0
}

func verb(apply bool) string {
	if apply {
		return "apply"
	}
	return "preview"
}

// runSnapshot implements `snapshot <graph.json> <snapshot.json>`. It reads and
// validates the current graph without modifying it, builds a deterministic,
// content-addressed snapshot, and saves it.
//
// Save rules, serialized against concurrent saves by an advisory lock on a
// sibling lock file:
//   - target absent: create it atomically (temp file + rename);
//   - target present, a valid snapshot of the same content: succeed and leave
//     the existing file's bytes untouched (idempotent);
//   - target present with different content, or corrupt/unreadable: refuse and
//     never overwrite it.
//
// The content identifier is printed only after the save has committed.
func runSnapshot(args []string) int {
	if len(args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: chainledger snapshot <graph.json> <snapshot.json>")
		return 2
	}
	graphPath := args[0]
	snapshotPath := args[1]

	graphData, err := os.ReadFile(graphPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read graph file %q: %v\n", graphPath, err)
		return 1
	}
	graph, err := chainledger.UnmarshalGraphFile(graphData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid graph file %q: %v\n", graphPath, err)
		return 1
	}
	snap, err := chainledger.BuildSnapshot(graph)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot build snapshot from %q: %v\n", graphPath, err)
		return 1
	}
	data, err := chainledger.MarshalSnapshot(snap)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot serialize snapshot: %v\n", err)
		return 1
	}

	// Hold a process-wide advisory lock for the whole check-then-write so
	// concurrent saves cannot interleave between inspecting the target and
	// committing the replacement.
	lock, err := acquireLock(snapshotPath + ".lock")
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot lock snapshot target %q: %v\n", snapshotPath, err)
		return 1
	}
	defer lock.release()

	existing, err := os.ReadFile(snapshotPath)
	switch {
	case err == nil:
		oldSnap, perr := chainledger.ParseSnapshot(existing)
		if perr != nil {
			fmt.Fprintf(os.Stderr, "error: refusing to overwrite %q: existing file is not a valid snapshot: %v\n", snapshotPath, perr)
			return 1
		}
		if oldSnap.ContentID != snap.ContentID {
			fmt.Fprintf(os.Stderr, "error: refusing to overwrite %q: it already holds a different snapshot (content %s); target content would be %s\n", snapshotPath, oldSnap.ContentID, snap.ContentID)
			return 1
		}
		// Same content: success without touching the file's bytes.
	case os.IsNotExist(err):
		if err := atomicWrite(snapshotPath, data); err != nil {
			fmt.Fprintf(os.Stderr, "error: cannot write snapshot file %q: %v\n", snapshotPath, err)
			return 1
		}
	default:
		fmt.Fprintf(os.Stderr, "error: cannot inspect snapshot target %q: %v\n", snapshotPath, err)
		return 1
	}

	// The save committed (or an identical snapshot was already present); only
	// now is the content identifier reported.
	fmt.Println(snap.ContentID)
	return 0
}

// runCompare implements `compare <old.json> <new.json>`: a strictly read-only
// comparison of two snapshots that prints the deterministic JSON report to
// stdout. It never writes to either file.
func runCompare(args []string) int {
	if len(args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: chainledger compare <old-snapshot.json> <new-snapshot.json>")
		return 2
	}
	oldPath := args[0]
	newPath := args[1]

	oldData, err := os.ReadFile(oldPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read old snapshot %q: %v\n", oldPath, err)
		return 1
	}
	oldSnap, err := chainledger.ParseSnapshot(oldData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid old snapshot %q: %v\n", oldPath, err)
		return 1
	}
	newData, err := os.ReadFile(newPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read new snapshot %q: %v\n", newPath, err)
		return 1
	}
	newSnap, err := chainledger.ParseSnapshot(newData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid new snapshot %q: %v\n", newPath, err)
		return 1
	}

	report := chainledger.CompareSnapshots(oldSnap, newSnap)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
		return 1
	}
	return 0
}

// runTrace implements `trace <snapshot.json> <dataset>`: a strictly read-only
// source trace against one snapshot that prints the deterministic JSON report
// to stdout. The whole snapshot is validated before the query runs; any
// failure is reported on stderr with a non-zero exit code and empty stdout,
// and the snapshot file is never modified.
func runTrace(args []string) int {
	if len(args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: chainledger trace <snapshot.json> <dataset>")
		return 2
	}
	snapshotPath := args[0]
	dataset := args[1]

	data, err := os.ReadFile(snapshotPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read snapshot %q: %v\n", snapshotPath, err)
		return 1
	}
	snap, err := chainledger.ParseSnapshot(data)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid snapshot %q: %v\n", snapshotPath, err)
		return 1
	}

	report, err := chainledger.TraceSources(snap, dataset)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot trace %q in snapshot %q: %v\n", dataset, snapshotPath, err)
		return 1
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
		return 1
	}
	return 0
}

// atomicWrite writes data to a temporary file in the same directory as path
// and renames it into place, so a write failure never leaves a partially
// written graph file: the original is preserved.
func atomicWrite(path string, data []byte) error {
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, ".chainledger-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	committed := false
	defer func() {
		if !committed {
			os.Remove(tmpName)
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmpName, path); err != nil {
		return err
	}
	committed = true
	return nil
}

func runDemo() {
	graph := map[string]*chainledger.Lineage{}
	register := func(dataset chainledger.Dataset, parents []string) {
		if err := chainledger.Register(graph, dataset, parents); err != nil {
			fmt.Printf("dataset=%s refused: %v\n", dataset.Name, err)
			return
		}
		fmt.Printf("dataset=%s registered parents=%v\n", dataset.Name, parents)
	}
	register(chainledger.Dataset{Name: "raw-blocks", SchemaVersion: 3}, nil)
	register(chainledger.Dataset{Name: "transfers", SchemaVersion: 2}, []string{"raw-blocks"})
	register(chainledger.Dataset{Name: "wallet-daily", SchemaVersion: 1}, []string{"transfers"})
	register(chainledger.Dataset{Name: "raw-blocks", SchemaVersion: 4}, []string{"wallet-daily"})
	fmt.Println("roots:", chainledger.Roots(graph))
	fmt.Printf("datasets=%d\n", len(graph))
}

